INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB001', '各项存款余额', '指机构吸收的全部存款期末余额，包括对公存款和个人存款，反映机构资金来源总规模', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB002', '各项贷款余额', '指机构发放的全部贷款期末余额，包括对公贷款和个人贷款，反映机构信贷投放总规模', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB003', '对公存款余额', '指机构吸收的企业、机关团体等单位存款期末余额，是机构低成本、稳定性负债的核心来源', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB004', '个人存款余额', '指机构吸收的个人储蓄存款期末余额，包括活期和定期储蓄存款', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB005', '对公贷款余额', '指向企业、事业单位等发放的贷款期末余额，是机构服务实体经济的重要体现', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB006', '个人贷款余额', '指向个人发放的贷款期末余额，包括住房按揭、消费贷和经营性贷款等', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB007', '中间业务收入', '指机构通过代理、结算、托管、咨询等非利差业务实现的收入，不含利息收入', '万元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB008', '净利息收入', '指机构利息收入减去利息支出后的净额，是传统存贷业务的核心盈利来源', '万元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB009', '营业收入', '指机构经营活动中实现的全部收入，含净利息收入、中间业务收入和投资收益等', '万元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB010', '营业支出', '指机构经营活动中发生的全部支出，含业务管理费、资产减值损失和税金等', '万元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB011', '净利润', '指营业收入扣除营业支出和所得税后的最终盈利，综合反映机构经营成果', '万元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB012', '成本收入比', '指营业支出与营业收入的比值，反映成本管控效率，数值越低说明经营效率越高', '%');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB013', '不良贷款率', '指不良贷款余额占各项贷款余额的比例，是衡量信贷资产质量的核心指标，监管要求低于5%', '%');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB014', '不良贷款余额', '指按五级分类认定的次级、可疑和损失类贷款余额，反映机构信用风险暴露程度', '亿元');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB015', '拨备覆盖率', '指贷款损失准备金与不良贷款余额的比率，反映风险抵补能力，监管要求不低于150%', '%');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB016', '资本充足率', '指资本净额与风险加权资产的比率，反映资本充足水平，监管要求不低于10.5%', '%');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB017', '逾期贷款率', '指逾期贷款余额占各项贷款余额的比例，反映贷款按期回收情况，数值越低越好', '%');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB018', '员工人数', '指机构在岗正式员工总数，反映人力资源规模', '人');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB019', '网点数量', '指机构下辖营业网点总数，含支行、分理处等物理渠道，反映服务覆盖面', '个');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB020', '个人客户数', '指机构服务的个人客户（含借记卡持卡人）总数，反映零售客群基础', '户');
INSERT INTO bank_metric_definition(metric_code, metric_name, metric_meaning, metric_unit) VALUES ('ZB021', '对公客户数', '指机构服务的企业及机构客户总数，反映对公客群基础', '户');
